package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.widget.*;
import org.json.*;
/** Account home with genuine summaries and recent library snapshots, not a simulated feed. */
final class DashboardView extends ScrollView {
 private final LinearLayout body,content,heroContent;private final TextView state;private final Button refresh;private boolean loading;
 private final Runnable gamesTab,mediaTab,steamTab;
 private final NativePresence presence;private final LinearLayout social,online,steamFriends;private JSONArray friends=new JSONArray(),events=new JSONArray();private TextView journey,friendsCount;private ProgressBar xpBar;private JSONObject peers=new JSONObject();private boolean active,socialBusy,steamBusy;private final android.os.Handler timer=new android.os.Handler();
 private final NativePresence.Listener listener=(value,connected)->{peers=value;renderOnline(connected);};
 private final Runnable tick=new Runnable(){public void run(){if(!active)return;loadSocial();timer.postDelayed(this,45000);}};
 void setForeground(boolean value){if(active==value)return;active=value;timer.removeCallbacks(tick);if(value){presence.listen(listener);tick.run();}else presence.remove(listener);}
 @Override protected void onDetachedFromWindow(){setForeground(false);super.onDetachedFromWindow();}
 private void loadSocial(){if(!socialBusy){socialBusy=true;new AccountRepository(getContext()).socialHome((rows,error)->{socialBusy=false;if(!active)return;if(error!=null){social.removeAllViews();social.addView(text(error,13,0xffb7a6ff));return;}JSONObject data=rows.optJSONObject(0);friends=data.optJSONArray("friends");events=data.optJSONArray("activity");renderOnline(true);renderActivity();});}if(steamBusy)return;steamBusy=true;new AccountRepository(getContext()).steamFriends((rows,error)->{steamBusy=false;if(!active)return;steamFriends.removeAllViews();steamFriends.addView(text("🎮 AMIGOS JOGANDO NA STEAM",13,0xffffba78));if(error!=null){steamFriends.addView(text(error,13,0xff9ca9b8));return;}JSONObject data=rows.optJSONObject(0);JSONArray games=data.optJSONArray("games");if(games.length()==0)steamFriends.addView(text(data.optInt("failed")>0?"Alguns perfis Steam não puderam ser consultados.":"Nenhum amigo com jogo visível na Steam agora.",13,0xff9ca9b8));for(int i=0;i<games.length();i++){JSONObject game=games.optJSONObject(i);LinearLayout tile=FriendHomeCard.create(getContext(),game.optString("name"),game.optString("game"),game.optString("cover"),game.optString("appid"),false);steamFriends.addView(tile);}});}
 private String activityKey(){return "activity_hidden_before:"+getContext().getSharedPreferences("batcaverna",0).getString("user_id","");}
 private void renderActivity(){social.removeAllViews();LinearLayout container=card();social.addView(container);LinearLayout header=new LinearLayout(getContext());header.setGravity(android.view.Gravity.CENTER_VERTICAL);header.addView(text("⚡ Atividade dos amigos",15,0xffd7c3ff),new LinearLayout.LayoutParams(0,-2,1));Button clear=new Button(getContext());clear.setText("Limpar");clear.setTextSize(11);clear.setMinWidth(0);AppStyle.button(clear,false);header.addView(clear,new LinearLayout.LayoutParams(dp(70),dp(40)));container.addView(header);clear.setOnClickListener(v->{getContext().getSharedPreferences("batcaverna",0).edit().putLong(activityKey(),System.currentTimeMillis()).apply();renderActivity();});long hidden=getContext().getSharedPreferences("batcaverna",0).getLong(activityKey(),0);int count=0;for(int i=0;i<events.length();i++){JSONObject e=events.optJSONObject(i);long stamp=MessageTime.epoch(e.optString("created_at"));if(stamp<=hidden)continue;count++;JSONObject author=e.optJSONObject("_author");LinearLayout row=new LinearLayout(getContext());row.setGravity(android.view.Gravity.CENTER_VERTICAL);row.setPadding(0,dp(8),0,dp(8));ImageView avatar=new ImageView(getContext());avatar.setImageResource(R.drawable.app_logo);avatar.setScaleType(ImageView.ScaleType.CENTER_CROP);avatar.setBackground(AppStyle.shape(avatar,0xff312a44,18));avatar.setClipToOutline(true);row.addView(avatar,new LinearLayout.LayoutParams(dp(36),dp(36)));if(author!=null)AccountImageLoader.load(avatar,author.optString("avatar_url"));LinearLayout info=new LinearLayout(getContext());info.setOrientation(LinearLayout.VERTICAL);info.setPadding(dp(10),0,dp(8),0);info.addView(text(author==null?"Amigo":author.optString("nome"),13,0xffe9dcff));TextView title=text(("jogos".equals(e.optString("categoria"))?"🎮 ":"🎬 ")+e.optString("nome"),12,0xfff3eff9);title.setMaxLines(2);info.addView(title);info.addView(text(e.optString("status"),10,0xffa99bbc));row.addView(info,new LinearLayout.LayoutParams(0,-2,1));row.addView(text(ActivityTime.relative(stamp,System.currentTimeMillis()),10,0xff9686b2));container.addView(row);android.view.View line=new android.view.View(getContext());line.setBackgroundColor(0x2236bda8);container.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));}if(count==0)container.addView(text("Nenhuma atividade nova. As próximas aparecerão aqui.",12,0xffa49bb5));clear.setEnabled(count>0);}
 private static String steamCover(JSONObject game){String cover=game.optString("cover","");String app=game.optString("appid","");if((cover.isEmpty()||cover.equals("null"))&&app.matches("[0-9]{1,12}"))return "https://cdn.cloudflare.steamstatic.com/steam/apps/"+app+"/header.jpg";return cover;}
 private void renderOnline(boolean connected){if(online==null)return;online.removeAllViews();online.addView(text("🟢 AMIGOS ONLINE • "+friends.length()+" na sua lista",13,0xffffba78));int count=0;for(int i=0;i<friends.length();i++){JSONObject friend=friends.optJSONObject(i),peer=peers.optJSONObject(friend.optString("id"));if(peer==null)continue;JSONArray metas=peer.optJSONArray("metas");JSONObject meta=metas==null?null:metas.optJSONObject(0);if(meta==null||"invisivel".equals(meta.optString("status")))continue;count++;int statusIndex=ProfileStatus.index(meta.optString("status","online"));LinearLayout friendCard=FriendHomeCard.create(getContext(),friend.optString("nome"),ProfileStatus.LABELS[statusIndex],friend.optString("avatar_url"),"",true);((TextView)((LinearLayout)friendCard.getChildAt(1)).getChildAt(1)).setTextColor(ProfileStatus.COLORS[statusIndex]);online.addView(friendCard);}if(count==0)online.addView(text(connected?"Nenhum amigo online neste momento.":"Conectando presença…",13,0xff9ca9b8));}

 DashboardView(Context c,Runnable games,Runnable media,Runnable steam,NativePresence live){super(c);presence=live;gamesTab=games;mediaTab=media;steamTab=steam;setFillViewport(true);setVerticalScrollBarEnabled(false);body=new LinearLayout(c);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(18),dp(16),dp(18),dp(24));addView(body);
  state=text("Preparando sua BatCaverna…",13,0xff9ca9b8);body.addView(state);LinearLayout release=card();release.addView(text("Novidades • Android 1.3.2",17,0xffbda3ff));release.addView(text("Indicações agora reconfirmam o título na sua biblioteca antes do envio. A busca de pessoas, os convites e as melhorias da biblioteca continuam disponíveis.",13,0xffd7cbe7));Button findFriend=new Button(c);findFriend.setText("Pesquisar e adicionar amigos");AppStyle.button(findFriend,true);findFriend.setOnClickListener(v->new FriendSearchSheet(c));release.addView(findFriend);body.addView(release);heroContent=new LinearLayout(c);heroContent.setOrientation(LinearLayout.VERTICAL);body.addView(heroContent);content=new LinearLayout(c);content.setOrientation(LinearLayout.VERTICAL);online=new LinearLayout(c);online.setOrientation(LinearLayout.VERTICAL);body.addView(online);steamFriends=new LinearLayout(c);steamFriends.setOrientation(LinearLayout.VERTICAL);social=new LinearLayout(c);social.setOrientation(LinearLayout.VERTICAL);body.addView(social);body.addView(steamFriends);body.addView(content);
  refresh=new Button(c);refresh.setText("Atualizar início");AppStyle.button(refresh,false);refresh.setOnClickListener(v->load());body.addView(refresh);load();
 }
 private void load(){if(loading)return;loading=true;refresh.setEnabled(false);state.setText("Carregando o resumo da sua conta…");new AccountRepository(getContext()).dashboard((rows,error)->{loading=false;refresh.setEnabled(true);if(error!=null){state.setText(error);return;}render(rows.optJSONObject(0));});}
 private void render(JSONObject data){if(data==null){state.setText("Resumo indisponível. Tente atualizar.");return;}content.removeAllViews();heroContent.removeAllViews();state.setText("BIBLIOTECA · COMUNIDADE · CONQUISTAS");
  JSONObject profile=data.optJSONObject("profile");String name=profile==null?"":profile.optString("nome","");if(name.equals("null"))name="";FrameLayout hero=new FrameLayout(getContext());hero.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff693aaa,0xff193651}));hero.setClipToOutline(true);hero.setOutlineProvider(new android.view.ViewOutlineProvider(){public void getOutline(android.view.View v,android.graphics.Outline o){o.setRoundRect(0,0,v.getWidth(),v.getHeight(),dp(22));}});
  ImageView cover=new ImageView(getContext());cover.setScaleType(ImageView.ScaleType.CENTER_CROP);hero.addView(cover,new FrameLayout.LayoutParams(-1,-1));if(profile!=null)AccountImageLoader.load(cover,profile.optString("banner_url",""));android.view.View shade=new android.view.View(getContext());shade.setBackground(new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0x33343057,0xee101419}));hero.addView(shade,new FrameLayout.LayoutParams(-1,-1));
  LinearLayout greeting=new LinearLayout(getContext());greeting.setOrientation(LinearLayout.VERTICAL);greeting.setPadding(dp(18),dp(18),dp(18),dp(18));greeting.addView(text("BEM-VINDO À BATCAVERNA",11,0xffc6b8ff));TextView welcome=text(name.isEmpty()?"O que vamos explorar hoje?":"Olá, "+name,25,0xfff3f4f8);welcome.setTypeface(null,Typeface.BOLD);welcome.setMaxLines(2);greeting.addView(welcome);journey=text("Carregando seu nível…",12,0xffdfcaef);greeting.addView(journey);xpBar=new ProgressBar(getContext(),null,android.R.attr.progressBarStyleHorizontal);xpBar.setMax(100);xpBar.setProgressTintList(android.content.res.ColorStateList.valueOf(0xffffc66f));greeting.addView(xpBar,new LinearLayout.LayoutParams(-1,dp(8)));hero.addView(greeting,new FrameLayout.LayoutParams(-1,-2,android.view.Gravity.BOTTOM));LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,dp(164));hp.setMargins(0,dp(8),0,dp(14));heroContent.addView(hero,hp);if(profile!=null){ImageView avatar=new ImageView(getContext());avatar.setImageResource(R.drawable.app_logo);avatar.setScaleType(ImageView.ScaleType.CENTER_CROP);avatar.setBackground(AppStyle.shape(avatar,0xff352442,24));avatar.setClipToOutline(true);FrameLayout.LayoutParams ap=new FrameLayout.LayoutParams(dp(42),dp(42),android.view.Gravity.RIGHT|android.view.Gravity.TOP);ap.setMargins(0,dp(12),dp(14),0);hero.addView(avatar,ap);AccountImageLoader.load(avatar,profile.optString("avatar_url"));}new AccountRepository(getContext()).ranking((rows,e)->{if(e!=null){journey.setText("Seu espaço de jogos e histórias");return;}String user=getContext().getSharedPreferences("batcaverna",0).getString("user_id","");for(int i=0;i<rows.length();i++){JSONObject me=rows.optJSONObject(i);if(user.equals(me.optString("id"))){long xp=me.optLong("xp");journey.setText(ProfileProgress.title(ProfileProgress.level(xp))+" • Nível "+ProfileProgress.level(xp)+"\n"+xp+" XP • "+(ProfileProgress.next(xp)-xp)+" para o próximo");xpBar.setProgress(ProfileProgress.percentage(xp));break;}}});
  String[] labels={"🎮 Jogos","🎬 Filmes e séries","🔥 Em andamento","🏁 Finalizados"};String[] keys={"total","media","playing","finished"};for(int row=0;row<2;row++){LinearLayout stats=new LinearLayout(getContext());for(int col=0;col<2;col++){int i=row*2+col;LinearLayout tile=card();tile.setPadding(dp(16),dp(12),dp(16),dp(12));TextView count=text(String.valueOf(data.optInt(keys[i])),25,0xffb7a6ff);count.setTypeface(null,Typeface.BOLD);tile.addView(count);tile.addView(text(labels[i],12,0xffb5bfcd));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(0,0,col==0?dp(10):0,dp(10));stats.addView(tile,lp);if(i==0)tile.setOnClickListener(v->gamesTab.run());if(i==1)tile.setOnClickListener(v->mediaTab.run());}heroContent.addView(stats);}
  LinearLayout progress=card();progress.addView(text("Sua jornada nos jogos",17,0xfff3f4f8));int total=data.optInt("total"),done=data.optInt("finished");int percent=total==0?0:Math.min(100,Math.max(0,(int)(100L*done/total)));progress.addView(text(done+" de "+total+" finalizados • "+percent+"%",13,0xff9ca9b8));ProgressBar bar=new ProgressBar(getContext(),null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);bar.setProgress(percent);bar.setProgressTintList(android.content.res.ColorStateList.valueOf(0xff9473ee));progress.addView(bar,new LinearLayout.LayoutParams(-1,dp(8)));content.addView(progress);
  section("JOGANDO AGORA",data.optJSONArray("games"),"Nenhum jogo em andamento.",gamesTab,true);

  TextView updatesTitle=text("ÚLTIMAS ALTERAÇÕES DA BIBLIOTECA",12,0xffffba78);updatesTitle.setTypeface(null,Typeface.BOLD);content.addView(updatesTitle);JSONArray updates=data.optJSONArray("updates");LinearLayout timeline=card();if(updates==null||updates.length()==0)timeline.addView(text("Nenhum título cadastrado ainda.",14,0xff9ca9b8));else for(int i=0;i<updates.length();i++){JSONObject item=updates.optJSONObject(i);if(item==null)continue;TextView t=text(item.optString("nome","Título"),15,0xfff3f4f8);t.setTypeface(null,Typeface.BOLD);timeline.addView(t);timeline.addView(text(("filmes".equals(item.optString("categoria"))?"Filmes e séries":"Jogos")+" • "+item.optString("status",""),12,0xff9ca9b8));}content.addView(timeline);
  Button steam=new Button(getContext());steam.setText("Explorar minha Steam");AppStyle.button(steam,false);steam.setOnClickListener(v->steamTab.run());content.addView(steam);
 }
 private void section(String heading,JSONArray entries,String empty,Runnable open,boolean games){TextView section=text(heading,12,0xffffba78);section.setTypeface(null,Typeface.BOLD);content.addView(section);if(entries==null||entries.length()==0){LinearLayout card=card();card.addView(text(empty,14,0xff9ca9b8));card.setOnClickListener(v->open.run());content.addView(card);return;}HorizontalScrollView shelf=new HorizontalScrollView(getContext());shelf.setHorizontalScrollBarEnabled(false);LinearLayout posters=new LinearLayout(getContext());shelf.addView(posters);content.addView(shelf);
  for(int i=0;i<entries.length();i++){JSONObject item=entries.optJSONObject(i);if(item==null)continue;String name=item.optString("nome","Título");if(name.isEmpty())name="Título";LinearLayout tile=new LinearLayout(getContext());tile.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(games?224:124),-2);lp.setMargins(0,dp(8),dp(12),dp(12));posters.addView(tile,lp);CoverArtwork artwork=new CoverArtwork(getContext());artwork.setBackground(AppStyle.shape(artwork,0xff2d3145,14));artwork.setClipToOutline(true);TextView fallback=text(name.substring(0,1),32,0xffb7a6ff);fallback.setGravity(android.view.Gravity.CENTER);artwork.addView(fallback,new FrameLayout.LayoutParams(-1,-1));ImageView image=new ImageView(getContext());image.setScaleType(ImageView.ScaleType.FIT_CENTER);artwork.image(image);artwork.addView(image,new FrameLayout.LayoutParams(-1,-1));tile.addView(artwork,new LinearLayout.LayoutParams(-1,-2));AccountImageLoader.load(image,item.optString("capa",""),games?item.optString("steam_appid",""):"");TextView title=text(name,14,0xfff3f4f8);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);tile.addView(title);tile.addView(text(item.optString("status",""),11,0xff9ca9b8));tile.setOnClickListener(v->open.run());}
 }
 private LinearLayout card(){LinearLayout v=new LinearLayout(getContext());v.setOrientation(LinearLayout.VERTICAL);v.setPadding(dp(14),dp(12),dp(14),dp(12));v.setBackground(AppStyle.shape(v,0xdd201b2c,20));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(8),0,dp(12));v.setLayoutParams(p);return v;}
 private TextView text(String s,int size,int color){TextView v=new TextView(getContext());v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setPadding(0,dp(4),0,dp(4));return v;}
 private int dp(int n){return AppStyle.dp(this,n);}
}
